function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var sorted := numbers.ToArray;
  sorted.Sort;
  var n := sorted.Length;
  for var i := 0 to n - 2 do
    if Abs(sorted[i] - sorted[i + 1]) > threshold then
    begin
      Result := True;
      exit;
    end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<char>;
  var res := new List<string>;
  var temp := new StringBuilder;
  var ignoreSpace := True;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];

    if ignoreSpace then
    begin
      if ch <> ' ' then
      begin
        ignoreSpace := False;
        temp.Append(ch);
      end;
    end
    else
    begin
      if ch = '(' then
        stack.Push(ch)
      else if ch = ')' then
      begin
        if stack.Count > 0 then
          stack.Pop
        else
          continue;

        if stack.Count = 0 then
          res.Add(temp.ToString)
        else
        begin
          var start := temp.Length + 1;
          for var j := start to temp.Length do
            if temp[j] = '(' then
            begin
              var subStr := temp.ToString;
              temp.Clear;
              temp.Append(subStr.Substring(start - 1, j - start + 1));
              break;
            end;
        end;
        temp.Clear;
      end
      else
        temp.Append(ch);
    end;
  end;

  Result := res.ToArray;
end;


