function MeanAbsoluteDeviation(numbers: array of real): real;
begin
  var mean := numbers.Average;
  var mad := 0.0;

  foreach var num in numbers do
    mad += Abs(num - mean);

  Result := mad / numbers.Length;
end;


function Intersperse(numbers: array of integer; delimeter: integer): array of integer;
begin
  if numbers.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;
  var res := new List<integer>;
  res.Add(numbers[0]);
  for var i := 1 to numbers.Length - 1 do
  begin
    res.Add(delimeter);
    res.Add(numbers[i]);
  end;
  Result := res.ToArray;
end;


function ParseNestedParens(parenString: string): array of integer;
begin
  var groups := parenString.Split(' ');
  var levels := new List<integer>;

  foreach var group in groups do
  begin
    var maxLevel := 0;
    var currentLevel := 0;

    for var i := 1 to group.Length do
    begin
      if group[i] = '(' then
        currentLevel += 1
      else if group[i] = ')' then
        currentLevel -= 1;

      if currentLevel > maxLevel then
        maxLevel := currentLevel;
    end;

    levels.Add(maxLevel);
  end;

  Result := levels.ToArray;
end;


