function SumProduct(numbers: array of integer): (integer, integer);
begin
  var sum := 0;
  var product := 1;
  foreach var num in numbers do
  begin
    sum += num;
    product *= num;
  end;
  Result := (sum, product);
end;


function RollingMax(numbers: array of integer): array of integer;
begin
  var maxList := new List<integer>;
  var currentMax := numbers[0];
  maxList.Add(numbers[0]);

  for var i := 1 to numbers.Length - 1 do
  begin
    if numbers[i] > currentMax then
      currentMax := numbers[i];
    maxList.Add(currentMax);
  end;

  Result := maxList.ToArray;
end;

