function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  var pal := str;
  for var i := 1 to n do
  begin
    var suffix := str.Substring(i);
    if IsPalindrome(suffix) then
    begin
      pal := str + ReverseString(str.Substring(0, i));
      break;
    end;
  end;
  Result := pal;
end;


