function HowManyTimes(str, substring: string): integer;
begin
  var count := 0;
  var start := 0;

  while start < str.Length do
  begin
    var pos := str.IndexOf(substring, start);
    if pos <> -1 then
    begin
      count += 1;
      start := pos + 1;
    end
    else
      break;
  end;

  Result := count;
end;


