function FindClosestElements(numbers: array of real): (real, real);
begin
  if numbers.Length < 2 then
  begin
    Result := (0, 0);
    exit;
  end;

  &Array.Sort(numbers);
  var minDiff := numbers[1] - numbers[0];
  var closest := (numbers[0], numbers[1]);

  for var i := 2 to numbers.Length - 1 do
  begin
    var diff := numbers[i] - numbers[i-1];
    if diff < minDiff then
    begin
      minDiff := diff;
      closest := (numbers[i-1], numbers[i]);
    end;
  end;

  Result := closest;
end;


function RescaleToUnit(numbers: array of real): array of real;
begin
  if numbers.Length < 2 then
  begin
    Result := numbers;
    exit;
  end;
  var minNum := numbers.Min;
  var maxNum := numbers.Max;
  var scale := 1.0 / (maxNum - minNum);
  for var i := 0 to numbers.Length - 1 do
    numbers[i] := (numbers[i] - minNum) * scale;
  Result := numbers;
end;


