function LargestDivisor(n: integer): integer;
begin
  var i := n - 1;
  while i >= 1 do
  begin
    if n mod i = 0 then
    begin
      Result := i;
      exit;
    end;
    i -= 1;
  end;
  Result := 1;
end;


function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var num := n;
  var factors := new List<integer>;
  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      num := num div i;
      factors.Add(i);
    end
    else
      i += 1;
  end;
  if num > 1 then
    factors.Add(num);
  Result := factors.ToArray;
end;


function RemoveDuplicates(numbers: array of integer): array of integer;
begin
