function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := False;
    exit;
  end;

  for var i := 2 to Trunc(Sqrt(n)) do
    if n mod i = 0 then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

