function SortThird(l: array of integer): array of integer;
begin
  var third := new List<integer>;
  var others := new List<integer>;
  var othersIndex := new List<integer>;

  for var i := 0 to l.Length - 1 do
    if i mod 3 = 0 then
      third.Add(l[i])
    else
    begin
      others.Add(l[i]);
      othersIndex.Add(i);
    end;

  third.Sort;

  for var i := 0 to third.Count - 1 do
    l[othersIndex[i]] := others[i];

  Result := l;
end;


