function Fib4(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 0
  else
  begin
    var fib := new integer[n + 1];
    fib[0] := 0;
    fib[1] := 0;
    fib[2] := 2;
    fib[3] := 0;

    for var i := 4 to n do
      fib[i] := fib[i - 1] + fib[i - 2] + fib[i - 3] + fib[i - 4];

    Result := fib[n];
  end;
end;


