      freq[num] := 1;

  var maxVal := -1;
  foreach var num in freq.Keys do
    if num <> maxVal then
    begin
      var count := freq[num];
      while count < num do
        count += 1;
      if count >= num then
        maxVal := num;
    end;
  Result := maxVal;
end;


