  var primes := new List<integer>;
  var n := a;

  while n <> 1 do
  begin
    var i := 2;
    while i * i <= n do
    begin
      if n mod i = 0 then
      begin
        primes.Add(i);
        n := n div i;
        break;
      end;
      i += 1;
    end;
  end;

  var primeCount := primes.Count;
  if primeCount < 3 then
    Result := false
  else
  begin
    var primeProduct := 1;
    foreach var prime in primes do
      primeProduct *= prime;

    Result := primeProduct = a;
  end;
end;


