function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var buckets := new integer[m, n];
  var count := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        buckets[i, j] := capacity;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if buckets[i, j] > 0 then
      begin
        var jj := j;
        while (jj > 0) and (buckets[i, jj - 1] = 0) and (grid[i][jj] = 1) do
        begin
          buckets[i, jj - 1] := buckets[i, jj] - 1;
          jj -= 1;
        end;
        if buckets[i, jj] > 0 then
          count += 1;
      end;

  Result := count;
end;


