  while left < right do
  begin
    var mid := (left + right) div 2;
    var currentChar := word[mid + 1];

    if vowels.Contains(currentChar) then
    begin
      closestVowel := currentChar;
      left := mid + 1;
    end
    else
      right := mid;
  end;

  Result := closestVowel;
end;


function MatchParens(lst: array of string): string;
begin
  var s := lst.JoinToString;
  var st := new Stack<char>;
  var bal := True;
  foreach var c in s do
  begin
    if c = '(' then
      st.Push(c)
    else if (st.Count > 0) and (st.Peek = '(') then
      st.Pop
    else
    begin
      bal := False;
      break;
    end;
  end;
  Result := bal and (st.Count = 0) ? 'Yes' : 'No';
end;


