function GetOddCollatz(n: integer): array of integer;
begin
  var oddNumbers := new List<integer>;
  var sequence := new List<integer>;

  if n = 1 then
  begin
    Result := sequence.ToArray;
    exit;
  end;

  for var i := 1 to n do
  begin
    if i mod 2 <> 0 then
      oddNumbers.Add(i);

    if i = 1 then
      sequence.Add(i)
    else if i mod 2 = 0 then
      sequence.Add(i div 2)
    else
      sequence.Add(3 * i + 1);
  end;

  Result := oddNumbers.ToArray;
end;


