begin
  var start1 := interval1[0];
  var end1 := interval1[1];
  var start2 := interval2[0];
  var end2 := interval2[1];

  var intersectionStart := Max(start1, start2);
  var intersectionEnd := Min(end1, end2);
  var intersectionLength := intersectionEnd - intersectionStart + 1;

  Result := if IsPrime(intersectionLength) then 'YES' else 'NO';
end;


function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var product := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    sign := sign * (num > 0 ? 1 : -1);
    product := product * Abs(num);
    sum := sum + Abs(num);
  end;

  Result := sign * product * sum;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var visited := new HashSet<(integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  var ans := new List<integer>;

  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i][j] = 1 then
        queue.Enqueue((i, j, 0));
    end;

  while queue.Count > 0 do
  begin
    var (i, j, steps) := queue.Dequeue;

    if steps = k then
    begin
      ans.Add(grid[i][j]);
      continue;
    end;

    foreach var (di, dj) in directions do
    begin
      var ni := i + di;
      var nj := j + dj;

      if (ni >= 0) and (ni < n) and (nj >= 0) and (nj < n) and 
         not visited.Contains((ni, nj)) then
      begin
        visited.Add((ni, nj));
        queue.Enqueue((ni, nj, steps + 1));
      end;
    end;
  end;

  Result := ans.ToArray;
end;


function Tri(n: integer): array of real;
begin
  var trib := new real[n + 1];
  trib[0] := 3;
  trib[1] := 1;
  trib[2] := 2;

  for var i := 3 to n do
    trib[i] := trib[i - 1] + trib[i - 2] + trib[i - 3];

  Result := trib;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 <> 0 then
    begin
      product *= digit;
      hasOdd := True;
    end;
    n := n div 10;
  end;
  Result := if hasOdd then product else 0;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '[' then
      stack.Push(ch)
    else if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


