function LargestSmallestIntegers(lst: array of integer): (integer, integer);
begin
  var largestNegative := integer.MinValue;
  var smallestPositive := integer.MaxValue;

  foreach var num in lst do
  begin
    if num < 0 then
      if num > largestNegative then
        largestNegative := num;
    else if num > 0 then
      if num < smallestPositive then
        smallestPositive := num;
  end;

  Result := (largestNegative, smallestPositive);
end;


function CompareOne(a, b: object): object;
begin
  var aType := TypeName(a);
  var bType := TypeName(b);

  if aType <> bType then
    raise new System.ArgumentException('Both variables must have the same type.');

  var aVal := a;
  var bVal := b;

  if aType = 'System.String' then
  begin
    var aStr := aVal as string;
    var bStr := bVal as string;

    if aStr.ToLower.EndsWith(',') then
      aVal := aStr.Substring(0, aStr.Length - 1)
    else if aStr.ToLower.EndsWith('.') then
      aVal := aStr.Substring(0, aStr.Length - 1);

    if bStr.ToLower.EndsWith(',') then
      bVal := bStr.Substring(0, bStr.Length - 1)
    else if bStr.ToLower.EndsWith('.') then
      bVal := bStr.Substring(0, bStr.Length - 1);

    aVal := StrToFloat(aVal);
    bVal := StrToFloat(bVal);
  end;

  var aNum := System.Convert.ToDouble(aVal);
  var bNum := System.Convert.ToDouble(bVal);

  if aNum > bNum then
    Result := aVal
  else if aNum < bNum then
    Result := bVal
  else
    Result := nil;
end;


function IsEqualToSumEven(n: integer): boolean;
begin
  if n mod 2 <> 0 then
    Result := False
  else
  begin
    var a := 2;
    var b := 2;
    var c := 2;
    var d := 2;
    while a + b + c + d < n do
    begin
      a += 2;
      b += 2;
      c += 2;
      d += 2;
    end;
    Result := a + b + c + d = n;
  end;
end;


function SpecialFactorial(n: integer): integer;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  var factorial := 1;
  for var i := 1 to n do
    factorial := factorial * i;

  var brazilianFactorial := 1;
  for var i := n downto 1 do
    brazilianFactorial := brazilianFactorial * i;

  Result := factorial * brazilianFactorial;
end;


function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var count := 0;

  for var i := 1 to text.Length do
  begin
    var ch := text[i];

    if ch = ' ' then
    begin
      if count = 0 then
        sb.Append(ch)
      else
      begin
        if count = 2 then
          sb.Append('-')
        else
          sb.Append('_');
        count := 0;
      end;
    end
    else
    begin
      sb.Append(ch);
      if ch = ' ' then
        count += 1;
      else
        count := 0;
    end;
  end;

  Result := sb.ToString;
end;


