    Result := 'No'
  else if (fileName.Substring(fileName.IndexOf('.')).Length > 3) or 
          (fileName.Substring(fileName.IndexOf('.')).IndexOfAny(['1', '2', '3', '4', '5', '6', '7', '8', '9', '0']) <> -1) then
    Result := 'No'
  else if (fileName.Substring(0, fileName.IndexOf('.')).Length = 0) or 
          (fileName.Substring(0, fileName.IndexOf('.')).IndexOfAny(['1', '2', '3', '4', '5', '6', '7', '8', '9', '0']) <> -1) then
    Result := 'No'
