  var sumDigits := new List<(integer, integer)>;

  for var i := 0 to nums.Length - 1 do
    sumDigits.Add((nums[i], i));

  sumDigits.Sort((x, y) -> 
  begin
    var sumX := x[0].ToString.Sum(ch -> StrToInt(ch.ToString));
    var sumY := y[0].ToString.Sum(ch -> StrToInt(ch.ToString));

    if sumX <> sumY then
      Result := sumX.CompareTo(sumY)
    else
      Result := x[1].CompareTo(y[1]);
  end);

  var res := new List<integer>;
  foreach var pair in sumDigits do
    res.Add(pair[0]);

  Result := res.ToArray;
end;


