    temp[i] := bs[i];

  for var i := 0 to n - 1 do
  begin
    for var j := 0 to n - 1 do
      bs[j] := temp[j];

    if a.Contains(new string(bs)) then
    begin
      Result := True;
      exit;
    end;

    for var j := 0 to n - 2 do
      temp[j + 1] := temp[j];
    temp[0] := bs[n - 1];
  end;

  Result := False;
end;


function EvenOddCount(num: integer): (integer, integer);
begin
  var even := 0;
  var odd := 0;
  var n := Abs(num);

  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 = 0 then
      even += 1
    else
      odd += 1;
    n := n div 10;
  end;

  Result := (even, odd);
end;


function IntToMiniRoman(number: integer): string;
begin
  if number = 0 then
  begin
    Result := '';
    exit;
  end;

  var values := |1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1|;
  var symbols := |'m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'|;

  var roman := '';
  var index := 0;

  while number > 0 do
  begin
    for var times := 1 to number div values[index] do
    begin
      roman += symbols[index];
      number -= values[index];
    end;
    index += 1;
  end;

  Result := roman;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
