function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var a := operand[0];
  for var i := 1 to operand.Length - 1 do
    case op[i-1] of
      '+': a += operand[i];
      '-': a -= operand[i];
      '*': a *= operand[i];
      '//': a := a div operand[i];
      '**': a := Round(Power(a, operand[i]));
    end;
  Result := a;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var letters := new List<char>;
  var special := new List<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if Char.IsLetter(ch) then
      letters.Add(ch)
    else
      special.Add(ch);
  end;

  if letters.Count = 0 then
  begin
    for var i := s.Length downto 1 do
    begin
      var ch := s[i];
      if Char.IsLetter(ch) then
        sb.Append(ch.ToUpper)
      else
        sb.Append(ch);
    end;
  end
  else
  begin
    var letterList := letters.ToList;
    for var i := 0 to letterList.Count - 1 do
    begin
      var ch := letterList[i];
      if Char.IsLower(ch) then
        letterList[i] := Char.ToUpper(ch)
      else
        letterList[i] := Char.ToLower(ch);
    end;

    for var i := 0 to letterList.Count - 1 do
      sb.Append(letterList[i]);

    for var i := 0 to special.Count - 1 do
      sb.Append(special[i]);
  end;

  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;
  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var bytes := Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);
  var sb := new System.StringBuilder;
  foreach var b in hash do
    sb.Append(b.ToString('x2'));
  Result := sb.ToString;
end;


